const statusColors = {
    'รอคิว': 'danger',
    'กำลังทำ': 'warning text-dark'
};

const nextStatus = {
    'รอคิว': 'กำลังทำ',
    'กำลังทำ': 'รอคิว'
};

let paymentModal;

async function fetchJobs() {
    const res = await fetch('/api/jobs');
    const data = await res.json();
    const tbody = document.getElementById('jobTable');
    tbody.innerHTML = '';

    if (data.length === 0) {
        tbody.innerHTML = `<tr><td colspan="5" class="text-center text-muted">🎉 ตอนนี้คิวงานว่างแล้ว!</td></tr>`;
        return;
    }

    data.forEach(j => {
        const color = statusColors[j.status] || 'secondary';
        let row = `<tr>
            <td><small class="text-muted fw-bold">#JOB-${String(j.id).padStart(4, '0')}</small></td>
            <td class="fw-bold">${j.customer_name}</td>
            <td>${j.details}</td>
            <td>
                <span class="badge rounded-pill bg-${color} status-badge p-2 shadow-sm" onclick="toggleStatus(${j.id}, '${j.status}')" title="คลิกเพื่อเปลี่ยนสถานะ">
                    ${j.status === 'รอคิว' ? '📝 ' : '⏳ '} ${j.status}
                </span>
            </td>
            <td>
                <button class="btn btn-sm btn-success rounded-pill shadow-sm fw-bold px-3" onclick="openPayment(${j.id})">💰 รับเงิน</button>
            </td>
        </tr>`;
        tbody.innerHTML += row;
    });
}

async function toggleStatus(id, currentStatus) {
    const newStatus = nextStatus[currentStatus];
    if (!newStatus) return;

    await fetch(`/api/jobs/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: newStatus })
    });
    fetchJobs();
}

function openPayment(id) {
    document.getElementById('payJobId').value = id;
    document.getElementById('payAmount').value = '';
    document.getElementById('payDiscount').value = '0';
    document.getElementById('payMethod').value = 'Cash';
    if (!paymentModal) {
        paymentModal = new bootstrap.Modal(document.getElementById('paymentModal'));
    }
    paymentModal.show();
}

async function submitPayment() {
    const id = document.getElementById('payJobId').value;
    const amount = parseFloat(document.getElementById('payAmount').value) || 0;
    const discount = parseFloat(document.getElementById('payDiscount').value) || 0;
    const method = document.getElementById('payMethod').value;

    if (amount <= 0) {
        alert("กรุณากรอกยอดเงินสุทธิที่ถูกต้อง");
        return;
    }

    const res = await fetch(`/api/jobs/${id}/complete`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            total_amount: amount,
            discount: discount,
            payment_method: method
        })
    });

    if (res.ok) {
        paymentModal.hide();
        fetchJobs();
    } else {
        alert("เกิดข้อผิดพลาดในการบันทึก");
    }
}

