let miniCart = [];

function renderMiniCart() {
    const list = document.getElementById('miniCartList');
    list.innerHTML = '';
    let total = 0;
    miniCart.forEach((item, index) => {
        total += (item.price * item.qty);
        list.innerHTML += `
            <li class="list-group-item d-flex justify-content-between align-items-center">
                <div style="flex:1;">
                    <small class="fw-bold">${item.name}</small>
                </div>
                <div class="d-flex align-items-center">
                    <input type="number" class="form-control form-control-sm text-center mx-2" style="width: 60px;" value="${item.qty}" min="1" onchange="updateMiniCartQty(${index}, this.value)">
                    <button class="btn btn-sm btn-outline-danger border-0" onclick="removeMiniCartItem(${index})">🗑</button>
                </div>
            </li>
        `;
    });
    if(miniCart.length > 0) {
        document.getElementById('payAmount').value = total;
    }
}

function updateMiniCartQty(index, qty) {
    miniCart[index].qty = parseInt(qty) || 1;
    renderMiniCart();
}

function removeMiniCartItem(index) {
    miniCart.splice(index, 1);
    renderMiniCart();
}

document.getElementById('searchProductForm').addEventListener('submit', async (e) => {
    e.preventDefault();
    const input = document.getElementById('productSearchInput');
    const query = input.value.trim();
    if (!query) return;

    const res = await fetch(`/api/products/search?q=${encodeURIComponent(query)}`);
    const products = await res.json();

    if (products.length > 0) {
        const p = products[0];
        const existing = miniCart.find(i => i.id === p.id);
        if (existing) {
            existing.qty += 1;
        } else {
            miniCart.push({ id: p.id, name: p.name, price: p.price, qty: 1 });
        }
        renderMiniCart();
        input.value = '';
    } else {
        alert('ไม่พบสินค้า!');
    }
});

function openPayment(id) {
    document.getElementById('payJobId').value = id;
    document.getElementById('payAmount').value = '';
    document.getElementById('payDiscount').value = '0';
    document.getElementById('payMethod').value = 'Cash';
    miniCart = [];
    renderMiniCart();

    if (!paymentModal) {
        paymentModal = new bootstrap.Modal(document.getElementById('paymentModal'));
    }
    paymentModal.show();

    // Focus search input after modal is shown
    document.getElementById('paymentModal').addEventListener('shown.bs.modal', function () {
        document.getElementById('productSearchInput').focus();
    }, { once: true });
}

async function submitPayment() {
    const id = document.getElementById('payJobId').value;
    const amount = parseFloat(document.getElementById('payAmount').value) || 0;
    const discount = parseFloat(document.getElementById('payDiscount').value) || 0;
    const method = document.getElementById('payMethod').value;

    if (amount <= 0 && miniCart.length === 0) {
        alert("กรุณากรอกยอดเงินสุทธิที่ถูกต้อง");
        return;
    }

    const res = await fetch(`/api/jobs/${id}/complete`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            total_amount: amount,
            discount: discount,
            payment_method: method,
            items: miniCart
        })
    });

    if (res.ok) {
        paymentModal.hide();
        fetchJobs();
    } else {
        alert("เกิดข้อผิดพลาดในการบันทึก");
    }
}

