document.getElementById('searchProductForm').addEventListener('submit', async (e) => {
    e.preventDefault();
    const input = document.getElementById('productSearchInput');
    const query = input.value.trim();
    if (!query) return;

    const res = await fetch(`/api/products/search?q=${encodeURIComponent(query)}`);
    const products = await res.json();

    if (products.length > 0) {
        // If form is submitted (e.g. by pressing Enter via scanner), just take the first match
        addProductToMiniCart(products[0]);
        input.value = '';
        document.getElementById('productSuggestions').classList.add('d-none');
    } else {
        alert('ไม่พบสินค้า!');
    }
});

function addProductToMiniCart(p) {
    const existing = miniCart.find(i => i.id === p.id);
    if (existing) {
        existing.qty += 1;
    } else {
        miniCart.push({ id: p.id, name: p.name, price: p.price, qty: 1 });
    }
    renderMiniCart();
}

// Autocomplete functionality
let searchTimeout = null;
document.getElementById('productSearchInput').addEventListener('input', (e) => {
    clearTimeout(searchTimeout);
    const query = e.target.value.trim();
    const suggestionsBox = document.getElementById('productSuggestions');

    if (!query) {
        suggestionsBox.classList.add('d-none');
        return;
    }

    searchTimeout = setTimeout(async () => {
        const res = await fetch(`/api/products/search?q=${encodeURIComponent(query)}`);
        const products = await res.json();

        suggestionsBox.innerHTML = '';
        if (products.length > 0) {
            products.forEach(p => {
                const item = document.createElement('button');
                item.type = 'button';
                item.className = 'list-group-item list-group-item-action text-start';
                item.innerHTML = `<strong>${p.name}</strong> <small class="text-muted ms-2">(${p.stock_qty} ชิ้น)</small> <span class="float-end text-success">฿${p.price.toFixed(2)}</span>`;
                item.onclick = () => {
                    addProductToMiniCart(p);
                    document.getElementById('productSearchInput').value = '';
                    suggestionsBox.classList.add('d-none');
                    document.getElementById('productSearchInput').focus();
                };
                suggestionsBox.appendChild(item);
            });
            suggestionsBox.classList.remove('d-none');
        } else {
            suggestionsBox.innerHTML = '<div class="list-group-item text-muted text-center">ไม่พบสินค้า</div>';
            suggestionsBox.classList.remove('d-none');
        }
    }, 300); // 300ms debounce
});

// Hide autocomplete when clicking outside
document.addEventListener('click', (e) => {
    if (!e.target.closest('#searchProductForm')) {
        document.getElementById('productSuggestions').classList.add('d-none');
    }
});

